import {test, expect, vi} from 'vitest';

function setup(stored: string | null) {
    vi.stubGlobal('window', {localStorage: {getItem: () => stored, setItem: () => {}}, navigator: {language: 'de-DE'}});
    vi.stubGlobal('document', {documentElement: {}});
}

test('render en/ru', async () => {
    const {App} = await import('./App');
    setup('ru');
    const ru = renderToString(<App />);
    setup('en');
    const en = renderToString(<App />);
    setup(null);
    const def = renderToString(<App />);
    const strip = (s: string) => s.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
    console.log('RU:', strip(ru));
    console.log('EN:', strip(en));
    expect(ru).toContain('Вы нажали 0 раз');
    expect(ru).toContain('Следующая');
    expect(en).toContain('You clicked 0 times');
    expect(en).toContain('Next');
    expect(def).toContain('Language switcher demo');
});
EOF
